def solve():
    n = int(input())
    nums = list(map(lambda x: x - 1, map(int, input().split())))
    cnt = 0
    for i in range(n):
        if nums[i] == i:
            continue
        swapped = False
        for j in range(i + 1, n):
            if nums[j] == i:
                nums[i], nums[j] = nums[j], nums[i]
                swapped = True
                break
        if not swapped:
            for j in range(i + 1, n):
                if nums[j] - 1 == i:
                    nums[j-1], nums[j] = nums[j], nums[j-1]
                    nums[i], nums[j] = nums[j], nums[i]
                    cnt += 2
        else:
            cnt += 1
    print(cnt)

