def solve():
    t = int(input())
    for _ in range(t):
        word = ''
        grid = []
        # get 8 lines
        for i, line in enumerate([list(x) for x in input().split()[:8]]):
            if any([j.isalpha() for j in line]):
                for c in line[::-1]:
                    if c.isalpha():
                        char = c
                        break
                word += char + ''
                grid.append(line)
        # check rest of the lines and write them out if they contain a letter
        while any(len(row) > 8 or not all([cell != '.' for cell in row]) for row in grid):
            new_grid = []
            for i, line in enumerate(grid[::-1]):
                if (len(line) < 8) & ('.' not in ''.join(line)):
                    word += ''.join(line)
                else:
                    new_row = ''
                    while len(new_row) < 8 and '.' != new_row[-1]:
                        for r in grid[::-1]:
                            if (len(r)) > 7 - i & ('.' not in r[7-i]):
                                char = r[7-i]
                                break
                        if new_row:
                            word += '' + (char or '')
                        else:
                            word = char + ''
                        new_row = char + new_row
                    if '.' != new_grid[-1][-8]:
                        grid.append(new_row)
                new_grid.append(line[::-1])
            grid = [x[::-1] for x in new_grid]
        # print the final read string
        print(word)

