def solve():
    n,k = map(int,input().split())
    if k == 1:
        return n

    total_ones = 0
    current_block, previous_block = n // k + (n % k != 0), 2 * n // k - 1
    current_total, previous_total = (k + (min(n % k, k)-1)) * k//2, max(0,(2*k-2)//2)

    for block in range(k+1, n+1):
        if block >= k and current_block > 0:
            total_ones += current_total
            previous_total = current_total
            current_total = (min(block % k, k))*block//2 + max((block // k) * (k-1) - (k*(n-block)//(k+1))//2,0)
            current_block -= 1

        if block <= n-k+(n%k)*(not bool(n%k)) and previous_block > 0:
            total_ones += previous_total
            current_total = previous_total
            previous_total = max(0,(block-previous_block)//k-(min(block, k)-1))

    return total_ones + (current_total*2 - n//k if current_total > 0 else math.ceil((n // k)))

