def solve(arr):
    sum_val = 0
    product = 1
    for num in arr:
        if num == -1: 
            sum_val -= 1
        elif num == 1:
            sum_val += 1
        product *= num
    operations = abs(sum_val) % 2 + (sum_val + product - len([num for num in arr if num == -1]) - ((product < 0)))//2
    return operations

