def solve():
    n = int(input())
    s = input()

    # Create a frequency dictionary for each pair of consecutive characters in the input string
    freq = defaultdict(int)
    res = 0

    for i in range(n - 1):
        x = (ord(s[i]) - ord('a')) * 10 + ord(s[(i % n) + 1] - ord('a'))
        if freq[x] == 0:
            res += 1
        freq[x] += 1

    # Handle pairs not occurring in the input string but present in its substring of length 2 starting from a given index
    for i in range(n):
        start = i + 1
        end = min(i + 10, n)
        while True:
            for j in range(start, end):
                x = (ord(s[i]) - ord('a')) * 10 + ord(s[j] - ord('a'))
                if freq[x] == 0:
                    res += 1
                freq[x] += 1
            start += 1
            end += 1
            if start >= n or end > n:
                break

    print(res)

