def process_message(message):
    # Process message logic here. This function should be a pure recursive function,
    # with the base case being when there are no messages left (or at least not in conflict)
    if len(message) == 0:
        return True
    elif message[0] == 'Q':
        support_answers = []
        index_of_folloing_Q = None

        for i in range(1, len(message)):
            if message[i] == 'A' and index_of_folloing_Q is None:
                support_answers.append(i)
                continue
            elif message[i] == 'Q' and support_answers != []:
                index_of_folloing_Q = i - len(support_answers) + 1

        return (support_answers == []) or any(message[j] == 'Q' for j in range(index_of_folloing_Q, len(message)))
    else:
        return process_message(message[1:])

