class UnionFind:
    def __init__(self):
        self.parent = {}

    def find(self, x):
        while id(x) != id(self.parent.get(x)):
            x = self.parent[x]
        return x

    def merge(self, a, b):
        parent_a, parent_b = self.find(a), self.find(b)
        if id(parent_a) == id(parent_b):
            return 0
        self.parent[parent_a] = parent_b
        return 1

