def sieve_of_eratosthenes(n):
    result = [True] * (n + 1)
    result[0:2] = [False, False]
    for current_prime in range(2, int(n**0.5) + 1):
        if result[current_prime]:
            for multiple in range(current_prime*2, n+1, current_prime):
                result[multiple] = False
    return [num for num, is_prime in enumerate(result) if is_prime]

def solve():
    p = []
    n = int(input())
    sieve = sieve_of_eratosthenes(n)
    primes = list(itertools.compress(sieve, sieve))
    i = 0
    while(i < n):
        p.append(primes[i])
        i += 2
    for j in range(i,n):
        if(j % 2 == 1):
            continue
        else:
            p[j], p[j-3] = p[j-3], p[j]
    return ' '.join(map(str, [num + 1 for num in p]))

